package com.example.agroconnect.model; import jakarta.persistence.*; import java.time.LocalDateTime;
@Entity @Table(name="loan_status_history") public class LoanStatusHistory {@Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(optional=false) @JoinColumn(name="loan_id") private Loan loan; private String previousStatus; private String newStatus; private String changedBy; private LocalDateTime changedAt=LocalDateTime.now(); @Column(length=1000) private String note; public Long getId(){return id;} public Loan getLoan(){return loan;} public void setLoan(Loan v){loan=v;} public String getPreviousStatus(){return previousStatus;} public void setPreviousStatus(String v){previousStatus=v;} public String getNewStatus(){return newStatus;} public void setNewStatus(String v){newStatus=v;} public String getChangedBy(){return changedBy;} public void setChangedBy(String v){changedBy=v;} public LocalDateTime getChangedAt(){return changedAt;} public String getNote(){return note;} public void setNote(String v){note=v;}}
